<?php
require_once 'functions.php'; require_roles(['admin','manager','staff']);verify_csrf();
if($_SERVER['REQUEST_METHOD']==='POST'){ $id=(int)$_POST['id'];$status=$_POST['status'];$allowed=['pending','approved','in_progress','ready','completed','cancelled'];if(in_array($status,$allowed,true)){$pdo->prepare('UPDATE customer_orders SET status=? WHERE id=?')->execute([$status,$id]);}header('Location: orders.php');exit;}
$rows=$pdo->query('SELECT * FROM customer_orders ORDER BY created_at DESC')->fetchAll();page_header('Customer orders');?>
<div class="hero"><div><p class="eyebrow">CUSTOMER REQUESTS</p><h1>Orders</h1><p>Review requests and update their progress.</p></div></div><section class="panel"><div class="tablewrap"><table><tr><th>Order</th><th>Customer</th><th>Phone</th><th>Notes</th><th>Status</th><th>Update</th></tr><?php foreach($rows as $r):?><tr><td>#<?=$r['id']?></td><td><?=h($r['customer_name'])?></td><td><?=h($r['phone'])?></td><td><?=h($r['notes'])?></td><td><?=h($r['status'])?></td><td><form method="post" class="inline"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status"><?php foreach(['pending','approved','in_progress','ready','completed','cancelled'] as $st):?><option <?=$r['status']===$st?'selected':''?>><?=$st?></option><?php endforeach;?></select><button>Save</button></form></td></tr><?php endforeach;?></table></div></section><?php page_footer();?>
